referenceSolutions.python:
def squareGaugesFirstQualifyingSlip(readings, k):
    a=readings
    out=[]
    for x in a:
        left,right=0,x+1
        while left+1<right:
            mid=(left+right)//2
            if mid*mid<=x: left=mid
            else: right=mid
        out.append(left)
    return next((x for x in out if x>=k),-1)

